INSERT INTO bible_versions (version_id, code, title, language, source_path) VALUES
('lxx', 'LXX', 'Septuaginta LXX', 'grc', 'resources/biblias/LXX.xml')
INSERT INTO bible_verses (version_id, ref, book, chapter, verse, text) VALUES
('lxx', 'Génesis 1:1', 'Génesis', 1, 1, 'εν αρχη εποιησεν ο θεος τον ουρανον και την γην'),
('lxx', 'Génesis 1:2', 'Génesis', 1, 2, 'η δε γη ην αορατος και ακατασκευαστος και σκοτος επανω της αβυσσου και πνευμα θεου επεφερετο επανω του υδατος'),
('lxx', 'Génesis 1:3', 'Génesis', 1, 3, 'και ειπεν ο θεος γενηθητω φως και εγενετο φως'),
('lxx', 'Génesis 1:4', 'Génesis', 1, 4, 'και ειδεν ο θεος το φως οτι καλον και διεχωρισεν ο θεος ανα μεσον του φωτος και ανα μεσον του σκοτους'),
('lxx', 'Génesis 1:5', 'Génesis', 1, 5, 'και εκαλεσεν ο θεος το φως ημεραν και το σκοτος εκαλεσεν νυκτα και εγενετο εσπερα και εγενετο πρωι ημερα μια'),
('lxx', 'Génesis 1:6', 'Génesis', 1, 6, 'και ειπεν ο θεος γενηθητω στερεωμα εν μεσω του υδατος και εστω διαχωριζον ανα μεσον υδατος και υδατος και εγενετο ουτως'),
('lxx', 'Génesis 1:7', 'Génesis', 1, 7, 'και εποιησεν ο θεος το στερεωμα και διεχωρισεν ο θεος ανα μεσον του υδατος ο ην υποκατω του στερεωματος και ανα μεσον του υδατος του επανω του στερεωματος'),
('lxx', 'Génesis 1:8', 'Génesis', 1, 8, 'και εκαλεσεν ο θεος το στερεωμα ουρανον και ειδεν ο θεος οτι καλον και εγενετο εσπερα και εγενετο πρωι ημερα δευτερα'),
('lxx', 'Génesis 1:9', 'Génesis', 1, 9, 'και ειπεν ο θεος συναχθητω το υδωρ το υποκατω του ουρανου εις συναγωγην μιαν και οφθητω η ξηρα και εγενετο ουτως και συνηχθη το υδωρ το υποκατω του ουρανου εις τας συναγωγας αυτων και ωφθη η ξηρα'),
('lxx', 'Génesis 1:10', 'Génesis', 1, 10, 'και εκαλεσεν ο θεος την ξηραν γην και τα συστηματα των υδατων εκαλεσεν θαλασσας και ειδεν ο θεος οτι καλον'),
('lxx', 'Génesis 1:11', 'Génesis', 1, 11, 'και ειπεν ο θεος βλαστησατω η γη βοτανην χορτου σπειρον σπερμα κατα γενος και καθ'' ομοιοτητα και ξυλον καρπιμον ποιουν καρπον ου το σπερμα αυτου εν αυτω κατα γενος επι της γης και εγενετο ουτως'),
('lxx', 'Génesis 1:12', 'Génesis', 1, 12, 'και εξηνεγκεν η γη βοτανην χορτου σπειρον σπερμα κατα γενος και καθ'' ομοιοτητα και ξυλον καρπιμον ποιουν καρπον ου το σπερμα αυτου εν αυτω κατα γενος επι της γης και ειδεν ο θεος οτι καλον'),
('lxx', 'Génesis 1:13', 'Génesis', 1, 13, 'και εγενετο εσπερα και εγενετο πρωι ημερα τριτη'),
('lxx', 'Génesis 1:14', 'Génesis', 1, 14, 'και ειπεν ο θεος γενηθητωσαν φωστηρες εν τω στερεωματι του ουρανου εις φαυσιν της γης του διαχωριζειν ανα μεσον της ημερας και ανα μεσον της νυκτος και εστωσαν εις σημεια και εις καιρους και εις ημερας και εις ενιαυτους'),
('lxx', 'Génesis 1:15', 'Génesis', 1, 15, 'και εστωσαν εις φαυσιν εν τω στερεωματι του ουρανου ωστε φαινειν επι της γης και εγενετο ουτως'),
('lxx', 'Génesis 1:16', 'Génesis', 1, 16, 'και εποιησεν ο θεος τους δυο φωστηρας τους μεγαλους τον φωστηρα τον μεγαν εις αρχας της ημερας και τον φωστηρα τον ελασσω εις αρχας της νυκτος και τους αστερας'),
('lxx', 'Génesis 1:17', 'Génesis', 1, 17, 'και εθετο αυτους ο θεος εν τω στερεωματι του ουρανου ωστε φαινειν επι της γης'),
('lxx', 'Génesis 1:18', 'Génesis', 1, 18, 'και αρχειν της ημερας και της νυκτος και διαχωριζειν ανα μεσον του φωτος και ανα μεσον του σκοτους και ειδεν ο θεος οτι καλον'),
('lxx', 'Génesis 1:19', 'Génesis', 1, 19, 'και εγενετο εσπερα και εγενετο πρωι ημερα τεταρτη'),
('lxx', 'Génesis 1:20', 'Génesis', 1, 20, 'και ειπεν ο θεος εξαγαγετω τα υδατα ερπετα ψυχων ζωσων και πετεινα πετομενα επι της γης κατα το στερεωμα του ουρανου και εγενετο ουτως'),
('lxx', 'Génesis 1:21', 'Génesis', 1, 21, 'και εποιησεν ο θεος τα κητη τα μεγαλα και πασαν ψυχην ζωων ερπετων α εξηγαγεν τα υδατα κατα γενη αυτων και παν πετεινον πτερωτον κατα γενος και ειδεν ο θεος οτι καλα'),
('lxx', 'Génesis 1:22', 'Génesis', 1, 22, 'και ηυλογησεν αυτα ο θεος λεγων αυξανεσθε και πληθυνεσθε και πληρωσατε τα υδατα εν ταις θαλασσαις και τα πετεινα πληθυνεσθωσαν επι της γης'),
('lxx', 'Génesis 1:23', 'Génesis', 1, 23, 'και εγενετο εσπερα και εγενετο πρωι ημερα πεμπτη'),
('lxx', 'Génesis 1:24', 'Génesis', 1, 24, 'και ειπεν ο θεος εξαγαγετω η γη ψυχην ζωσαν κατα γενος τετραποδα και ερπετα και θηρια της γης κατα γενος και εγενετο ουτως'),
('lxx', 'Génesis 1:25', 'Génesis', 1, 25, 'και εποιησεν ο θεος τα θηρια της γης κατα γενος και τα κτηνη κατα γενος και παντα τα ερπετα της γης κατα γενος αυτων και ειδεν ο θεος οτι καλα'),
('lxx', 'Génesis 1:26', 'Génesis', 1, 26, 'και ειπεν ο θεος ποιησωμεν ανθρωπον κατ'' εικονα ημετεραν και καθ'' ομοιωσιν και αρχετωσαν των ιχθυων της θαλασσης και των πετεινων του ουρανου και των κτηνων και πασης της γης και παντων των ερπετων των ερποντων επι της γης'),
('lxx', 'Génesis 1:27', 'Génesis', 1, 27, 'και εποιησεν ο θεος τον ανθρωπον κατ'' εικονα θεου εποιησεν αυτον αρσεν και θηλυ εποιησεν αυτους'),
('lxx', 'Génesis 1:28', 'Génesis', 1, 28, 'και ηυλογησεν αυτους ο θεος λεγων αυξανεσθε και πληθυνεσθε και πληρωσατε την γην και κατακυριευσατε αυτης και αρχετε των ιχθυων της θαλασσης και των πετεινων του ουρανου και παντων των κτηνων και πασης της γης και παντων των ερπετων των ερποντων επι της γης'),
('lxx', 'Génesis 1:29', 'Génesis', 1, 29, 'και ειπεν ο θεος ιδου δεδωκα υμιν παν χορτον σποριμον σπειρον σπερμα ο εστιν επανω πασης της γης και παν ξυλον ο εχει εν εαυτω καρπον σπερματος σποριμου υμιν εσται εις βρωσιν'),
('lxx', 'Génesis 1:30', 'Génesis', 1, 30, 'και πασι τοις θηριοις της γης και πασι τοις πετεινοις του ουρανου και παντι ερπετω τω ερποντι επι της γης ο εχει εν εαυτω ψυχην ζωης παντα χορτον χλωρον εις βρωσιν και εγενετο ουτως'),
('lxx', 'Génesis 1:31', 'Génesis', 1, 31, 'και ειδεν ο θεος τα παντα οσα εποιησεν και ιδου καλα λιαν και εγενετο εσπερα και εγενετο πρωι ημερα εκτη'),
('lxx', 'Génesis 2:1', 'Génesis', 2, 1, 'και συνετελεσθησαν ο ουρανος και η γη και πας ο κοσμος αυτων'),
('lxx', 'Génesis 2:2', 'Génesis', 2, 2, 'και συνετελεσεν ο θεος εν τη ημερα τη εκτη τα εργα αυτου α εποιησεν και κατεπαυσεν τη ημερα τη εβδομη απο παντων των εργων αυτου ων εποιησεν'),
('lxx', 'Génesis 2:3', 'Génesis', 2, 3, 'και ηυλογησεν ο θεος την ημεραν την εβδομην και ηγιασεν αυτην οτι εν αυτη κατεπαυσεν απο παντων των εργων αυτου ων ηρξατο ο θεος ποιησαι'),
('lxx', 'Génesis 2:4', 'Génesis', 2, 4, 'αυτη η βιβλος γενεσεως ουρανου και γης οτε εγενετο η ημερα εποιησεν ο θεος τον ουρανον και την γην'),
('lxx', 'Génesis 2:5', 'Génesis', 2, 5, 'και παν χλωρον αγρου προ του γενεσθαι επι της γης και παντα χορτον αγρου προ του ανατειλαι ου γαρ εβρεξεν ο θεος επι την γην και ανθρωπος ουκ ην εργαζεσθαι την γην'),
('lxx', 'Génesis 2:6', 'Génesis', 2, 6, 'πηγη δε ανεβαινεν εκ της γης και εποτιζεν παν το προσωπον της γης'),
('lxx', 'Génesis 2:7', 'Génesis', 2, 7, 'και επλασεν ο θεος τον ανθρωπον χουν απο της γης και ενεφυσησεν εις το προσωπον αυτου πνοην ζωης και εγενετο ο ανθρωπος εις ψυχην ζωσαν'),
('lxx', 'Génesis 2:8', 'Génesis', 2, 8, 'και εφυτευσεν κυριος ο θεος παραδεισον εν εδεμ κατα ανατολας και εθετο εκει τον ανθρωπον ον επλασεν'),
('lxx', 'Génesis 2:9', 'Génesis', 2, 9, 'και εξανετειλεν ο θεος ετι εκ της γης παν ξυλον ωραιον εις ορασιν και καλον εις βρωσιν και το ξυλον της ζωης εν μεσω τω παραδεισω και το ξυλον του ειδεναι γνωστον καλου και πονηρου'),
('lxx', 'Génesis 2:10', 'Génesis', 2, 10, 'ποταμος δε εκπορευεται εξ εδεμ ποτιζειν τον παραδεισον εκειθεν αφοριζεται εις τεσσαρας αρχας'),
('lxx', 'Génesis 2:11', 'Génesis', 2, 11, 'ονομα τω ενι φισων ουτος ο κυκλων πασαν την γην ευιλατ εκει ου εστιν το χρυσιον'),
('lxx', 'Génesis 2:12', 'Génesis', 2, 12, 'το δε χρυσιον της γης εκεινης καλον και εκει εστιν ο ανθραξ και ο λιθος ο πρασινος'),
('lxx', 'Génesis 2:13', 'Génesis', 2, 13, 'και ονομα τω ποταμω τω δευτερω γηων ουτος ο κυκλων πασαν την γην αιθιοπιας'),
('lxx', 'Génesis 2:14', 'Génesis', 2, 14, 'και ο ποταμος ο τριτος τιγρις ουτος ο πορευομενος κατεναντι ασσυριων ο δε ποταμος ο τεταρτος ουτος ευφρατης'),
('lxx', 'Génesis 2:15', 'Génesis', 2, 15, 'και ελαβεν κυριος ο θεος τον ανθρωπον ον επλασεν και εθετο αυτον εν τω παραδεισω εργαζεσθαι αυτον και φυλασσειν'),
('lxx', 'Génesis 2:16', 'Génesis', 2, 16, 'και ενετειλατο κυριος ο θεος τω αδαμ λεγων απο παντος ξυλου του εν τω παραδεισω βρωσει φαγη'),
('lxx', 'Génesis 2:17', 'Génesis', 2, 17, 'απο δε του ξυλου του γινωσκειν καλον και πονηρον ου φαγεσθε απ'' αυτου η δ'' αν ημερα φαγητε απ'' αυτου θανατω αποθανεισθε'),
('lxx', 'Génesis 2:18', 'Génesis', 2, 18, 'και ειπεν κυριος ο θεος ου καλον ειναι τον ανθρωπον μονον ποιησωμεν αυτω βοηθον κατ'' αυτον'),
('lxx', 'Génesis 2:19', 'Génesis', 2, 19, 'και επλασεν ο θεος ετι εκ της γης παντα τα θηρια του αγρου και παντα τα πετεινα του ουρανου και ηγαγεν αυτα προς τον αδαμ ιδειν τι καλεσει αυτα και παν ο εαν εκαλεσεν αυτο αδαμ ψυχην ζωσαν τουτο ονομα αυτου'),
('lxx', 'Génesis 2:20', 'Génesis', 2, 20, 'και εκαλεσεν αδαμ ονοματα πασιν τοις κτηνεσιν και πασι τοις πετεινοις του ουρανου και πασι τοις θηριοις του αγρου τω δε αδαμ ουχ ευρεθη βοηθος ομοιος αυτω'),
('lxx', 'Génesis 2:21', 'Génesis', 2, 21, 'και επεβαλεν ο θεος εκστασιν επι τον αδαμ και υπνωσεν και ελαβεν μιαν των πλευρων αυτου και ανεπληρωσεν σαρκα αντ'' αυτης'),
('lxx', 'Génesis 2:22', 'Génesis', 2, 22, 'και ωκοδομησεν κυριος ο θεος την πλευραν ην ελαβεν απο του αδαμ εις γυναικα και ηγαγεν αυτην προς τον αδαμ'),
('lxx', 'Génesis 2:23', 'Génesis', 2, 23, 'και ειπεν αδαμ τουτο νυν οστουν εκ των οστεων μου και σαρξ εκ της σαρκος μου αυτη κληθησεται γυνη οτι εκ του ανδρος αυτης ελημφθη αυτη'),
('lxx', 'Génesis 2:24', 'Génesis', 2, 24, 'ενεκεν τουτου καταλειψει ανθρωπος τον πατερα αυτου και την μητερα αυτου και προσκολληθησεται προς την γυναικα αυτου και εσονται οι δυο εις σαρκα μιαν'),
('lxx', 'Génesis 2:25', 'Génesis', 2, 25, 'και ησαν οι δυο γυμνοι ο τε αδαμ και η γυνη αυτου και ουκ ησχυνοντο'),
('lxx', 'Génesis 3:1', 'Génesis', 3, 1, 'ο δε οφις ην φρονιμωτατος παντων των θηριων των επι της γης ων εποιησεν κυριος ο θεος και ειπεν ο οφις τη γυναικι τι οτι ειπεν ο θεος ου μη φαγητε απο παντος ξυλου του εν τω παραδεισω'),
('lxx', 'Génesis 3:2', 'Génesis', 3, 2, 'και ειπεν η γυνη τω οφει απο καρπου ξυλου του παραδεισου φαγομεθα'),
('lxx', 'Génesis 3:3', 'Génesis', 3, 3, 'απο δε καρπου του ξυλου ο εστιν εν μεσω του παραδεισου ειπεν ο θεος ου φαγεσθε απ'' αυτου ουδε μη αψησθε αυτου ινα μη αποθανητε'),
('lxx', 'Génesis 3:4', 'Génesis', 3, 4, 'και ειπεν ο οφις τη γυναικι ου θανατω αποθανεισθε'),
('lxx', 'Génesis 3:5', 'Génesis', 3, 5, 'ηδει γαρ ο θεος οτι εν η αν ημερα φαγητε απ'' αυτου διανοιχθησονται υμων οι οφθαλμοι και εσεσθε ως θεοι γινωσκοντες καλον και πονηρον'),
('lxx', 'Génesis 3:6', 'Génesis', 3, 6, 'και ειδεν η γυνη οτι καλον το ξυλον εις βρωσιν και οτι αρεστον τοις οφθαλμοις ιδειν και ωραιον εστιν του κατανοησαι και λαβουσα του καρπου αυτου εφαγεν και εδωκεν και τω ανδρι αυτης μετ'' αυτης και εφαγον'),
('lxx', 'Génesis 3:7', 'Génesis', 3, 7, 'και διηνοιχθησαν οι οφθαλμοι των δυο και εγνωσαν οτι γυμνοι ησαν και ερραψαν φυλλα συκης και εποιησαν εαυτοις περιζωματα'),
('lxx', 'Génesis 3:8', 'Génesis', 3, 8, 'και ηκουσαν την φωνην κυριου του θεου περιπατουντος εν τω παραδεισω το δειλινον και εκρυβησαν ο τε αδαμ και η γυνη αυτου απο προσωπου κυριου του θεου εν μεσω του ξυλου του παραδεισου'),
('lxx', 'Génesis 3:9', 'Génesis', 3, 9, 'και εκαλεσεν κυριος ο θεος τον αδαμ και ειπεν αυτω αδαμ που ει'),
('lxx', 'Génesis 3:10', 'Génesis', 3, 10, 'και ειπεν αυτω την φωνην σου ηκουσα περιπατουντος εν τω παραδεισω και εφοβηθην οτι γυμνος ειμι και εκρυβην'),
('lxx', 'Génesis 3:11', 'Génesis', 3, 11, 'και ειπεν αυτω τις ανηγγειλεν σοι οτι γυμνος ει μη απο του ξυλου ου ενετειλαμην σοι τουτου μονου μη φαγειν απ'' αυτου εφαγες'),
('lxx', 'Génesis 3:12', 'Génesis', 3, 12, 'και ειπεν ο αδαμ η γυνη ην εδωκας μετ'' εμου αυτη μοι εδωκεν απο του ξυλου και εφαγον'),
('lxx', 'Génesis 3:13', 'Génesis', 3, 13, 'και ειπεν κυριος ο θεος τη γυναικι τι τουτο εποιησας και ειπεν η γυνη ο οφις ηπατησεν με και εφαγον'),
('lxx', 'Génesis 3:14', 'Génesis', 3, 14, 'και ειπεν κυριος ο θεος τω οφει οτι εποιησας τουτο επικαταρατος συ απο παντων των κτηνων και απο παντων των θηριων της γης επι τω στηθει σου και τη κοιλια πορευση και γην φαγη πασας τας ημερας της ζωης σου'),
('lxx', 'Génesis 3:15', 'Génesis', 3, 15, 'και εχθραν θησω ανα μεσον σου και ανα μεσον της γυναικος και ανα μεσον του σπερματος σου και ανα μεσον του σπερματος αυτης αυτος σου τηρησει κεφαλην και συ τηρησεις αυτου πτερναν'),
('lxx', 'Génesis 3:16', 'Génesis', 3, 16, 'και τη γυναικι ειπεν πληθυνων πληθυνω τας λυπας σου και τον στεναγμον σου εν λυπαις τεξη τεκνα και προς τον ανδρα σου η αποστροφη σου και αυτος σου κυριευσει'),
('lxx', 'Génesis 3:17', 'Génesis', 3, 17, 'τω δε αδαμ ειπεν οτι ηκουσας της φωνης της γυναικος σου και εφαγες απο του ξυλου ου ενετειλαμην σοι τουτου μονου μη φαγειν απ'' αυτου επικαταρατος η γη εν τοις εργοις σου εν λυπαις φαγη αυτην πασας τας ημερας της ζωης σου'),
('lxx', 'Génesis 3:18', 'Génesis', 3, 18, 'ακανθας και τριβολους ανατελει σοι και φαγη τον χορτον του αγρου'),
('lxx', 'Génesis 3:19', 'Génesis', 3, 19, 'εν ιδρωτι του προσωπου σου φαγη τον αρτον σου εως του αποστρεψαι σε εις την γην εξ ης ελημφθης οτι γη ει και εις γην απελευση'),
('lxx', 'Génesis 3:20', 'Génesis', 3, 20, 'και εκαλεσεν αδαμ το ονομα της γυναικος αυτου ζωη οτι αυτη μητηρ παντων των ζωντων'),
('lxx', 'Génesis 3:21', 'Génesis', 3, 21, 'και εποιησεν κυριος ο θεος τω αδαμ και τη γυναικι αυτου χιτωνας δερματινους και ενεδυσεν αυτους'),
('lxx', 'Génesis 3:22', 'Génesis', 3, 22, 'και ειπεν ο θεος ιδου αδαμ γεγονεν ως εις εξ ημων του γινωσκειν καλον και πονηρον και νυν μηποτε εκτεινη την χειρα και λαβη του ξυλου της ζωης και φαγη και ζησεται εις τον αιωνα'),
('lxx', 'Génesis 3:23', 'Génesis', 3, 23, 'και εξαπεστειλεν αυτον κυριος ο θεος εκ του παραδεισου της τρυφης εργαζεσθαι την γην εξ ης ελημφθη'),
('lxx', 'Génesis 3:24', 'Génesis', 3, 24, 'και εξεβαλεν τον αδαμ και κατωκισεν αυτον απεναντι του παραδεισου της τρυφης και εταξεν τα χερουβιμ και την φλογινην ρομφαιαν την στρεφομενην φυλασσειν την οδον του ξυλου της ζωης'),
('lxx', 'Génesis 4:1', 'Génesis', 4, 1, 'αδαμ δε εγνω ευαν την γυναικα αυτου και συλλαβουσα ετεκεν τον καιν και ειπεν εκτησαμην ανθρωπον δια του θεου'),
('lxx', 'Génesis 4:2', 'Génesis', 4, 2, 'και προσεθηκεν τεκειν τον αδελφον αυτου τον αβελ και εγενετο αβελ ποιμην προβατων καιν δε ην εργαζομενος την γην'),
('lxx', 'Génesis 4:3', 'Génesis', 4, 3, 'και εγενετο μεθ'' ημερας ηνεγκεν καιν απο των καρπων της γης θυσιαν τω κυριω'),
